def calculate_a(n, memo):
    if n <= 0:
        raise ValueError("n must be positive")
    if n in memo:
        return memo[n]

    if n == 1 or n == 2:
        return 1

    # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}

    try:
        a_n_minus_1 = calculate_a(n - 1, memo)
    except RecursionError:
        # Handle potential deep recursion if we were calculating much higher,
        # but for n=32 it should be fine with memoization.
        return None 

    try:
        term1 = calculate_a(a_n_minus_1, memo)
        term2 = calculate_a(n - a_n_minus_1, memo)
        result = term1 + term2
    except RecursionError:
        return None

    memo[n] = result
    return result

# Initialize memoization dictionary
memo = {}

# Calculate up to n=32
for n in range(1, 33):
    if n > 1 and n not in memo:
        try:
            a_n = calculate_a(n, memo)
            if a_n is None:
                print(f"Error calculating a_{n}")
                break
            print(f"a_{n} = {a_n}")
        except RecursionError:
            print(f"Recursion limit reached at n={n}")
            break

# Extract required values
print("\n--- Check Powers of 2 ---")
powers_of_2 = [2**k for k in range(1, 6)] # 2, 4, 8, 16, 32
for p in powers_of_2:
    print(f"a_{p} = {memo[p]}")

def generate_sequence_extended(N):
    results = {}
    results[1] = 1
    results[2] = 1

    for n in range(3, N + 1):
        # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}

        # We assume results[n-1] exists
        a_n_minus_1 = results[n-1]

        if n - a_n_minus_1 < 1:
             # This should not happen for the values observed so far
             print(f"Error: Index out of bounds at n={n}")
             break

        # We must assume results[a_n_minus_1] and results[n - a_n_minus_1] exist.
        # Since a_k seems to grow roughly linearly, the indices a_{n-1} and n - a_{n-1} 
        # should be less than n, so they should be in the 'results' dictionary.

        try:
            term1 = results[a_n_minus_1]
            term2 = results[n - a_n_minus_1]
            results[n] = term1 + term2
        except KeyError as e:
            print(f"Error: Dependency missing at n={n}. Missing key: {e}")
            break

    return results

N_calc = 100
sequence = generate_sequence_extended(N_calc)

print("n | a_n")
print("--------------------")
for n in range(1, N_calc + 1):
    if n % 10 == 0 or n <= 15 or n == 40 or n == 100:
        print(f"{n:2} | {sequence[n]}")

print("\n--- Full list of small terms for pattern inspection ---")
for n in range(1, 16):
    print(f"a_{n:2} = {sequence[n]}")
